/* AMC8 1998 #14S */
label("Math", (0,72), SE);
label("Science", (60, 72), SE);
label("$28+12=40$", (46, 10), N);
draw(Circle((30,45), 20));
draw(Circle((57, 45), 17));
label("28", (30,45));
label("3", (57,45));
label("12", (44.5, 45));
[/asy]

